import 'package:flutter/material.dart';

import 'screens/home_screen.dart';

void main() => runApp(const ShopApp());

class ShopApp extends StatelessWidget {
  const ShopApp({super.key});

  @override
  Widget build(BuildContext context) => const MaterialApp(home: HomeScreen());
}

class Product {
  const Product(this.name);

  final String name;
}

import 'package:flutter/material.dart';

import '../models/product.dart';
import '../widgets/product_tile.dart';

class HomeScreen extends StatelessWidget {
  const HomeScreen({super.key});

  static const _products = [Product('Mug')];

  @override
  Widget build(BuildContext context) => Scaffold(
    body: ListView(
      children: [for (final item in _products) ProductTile(product: item)],
    ),
  );
}

import 'package:flutter/material.dart';

import '../models/product.dart';

class ProductTile extends StatelessWidget {
  const ProductTile({required this.product, super.key});

  final Product product;

  @override
  Widget build(BuildContext context) => ListTile(title: Text(product.name));
}
